using System.Collections;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEngine.UIElements;
using ShorelineDefense.Core;
using ShorelineDefense.Building;
using ShorelineDefense.Defenses;
using ShorelineDefense.Enemies;
using ShorelineDefense.Waves;
using ShorelineDefense.UI;
using ShorelineDefense.Economy;
namespace ShorelineDefense.Tests {
 public sealed class Phase4CPlayTests {
  BuildManager build;WaveManager waves;EnemySpawner spawn;EnemyRegistry registry;BorderBreachService border;RunStatistics stats;
  [UnitySetUp] public IEnumerator Setup(){Time.timeScale=0;yield return SceneManager.LoadSceneAsync("Assets/Game/Scenes/CoastalDefense_TopDown.unity");yield return null;build=Object.FindFirstObjectByType<BuildManager>();waves=Object.FindFirstObjectByType<WaveManager>();spawn=Object.FindFirstObjectByType<EnemySpawner>();registry=Object.FindFirstObjectByType<EnemyRegistry>();border=Object.FindFirstObjectByType<BorderBreachService>();stats=Object.FindFirstObjectByType<RunStatistics>();border.ConfigureThreshold(0);build.Economy.AddMoney(20000);}
  [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;var previous=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("Phase4C cleanup"));yield return SceneManager.UnloadSceneAsync(previous);LogAssert.NoUnexpectedReceived();}
  [UnityTest]public IEnumerator DismantleEveryDefenseRefundsPaidCostOnceAndClearsFootprint(){var catalog=Object.FindFirstObjectByType<BuildHud>().Defenses;foreach(var d in catalog){var cell=new Vector2Int(18,8);Assert.AreEqual(PlacementResult.Valid,build.TryPlaceDefense(d,cell,out var defense));int money=build.Economy.Money;long earned=build.Economy.TotalEarned;Assert.IsTrue(build.TryDismantle(defense,out int refund));Assert.AreEqual(d.Cost/2,refund);Assert.AreEqual(money+refund,build.Economy.Money);Assert.AreEqual(earned,build.Economy.TotalEarned);Assert.IsFalse(build.TryDismantle(defense,out _));for(int x=0;x<d.Footprint.x;x++)for(int y=0;y<d.Footprint.y;y++)Assert.IsNull(build.Battlefield.Grid.OccupantAt(cell+new Vector2Int(x,y)));Assert.IsFalse(defense.IsAlive);yield return null;}Assert.AreEqual(8,build.Economy.StructuresDismantled);Assert.Greater(build.Economy.RefundIncome,0);}
  [UnityTest]public IEnumerator WireNeighborsNavigationAndSelectionCleanUpDuringCombat(){var wire=Object.FindFirstObjectByType<BuildHud>().Defenses.First(d=>d.Id=="barbed-wire");build.TryPlaceDefense(wire,new Vector2Int(18,8),out var a);build.TryPlaceDefense(wire,new Vector2Int(19,8),out var b);var art=b.GetComponent<ShorelineDefense.Presentation.ConnectedWirePresentation>();Assert.AreEqual(8,art.Mask);int revision=build.Battlefield.Grid.Revision;Assert.IsTrue(waves.TryStartWave());Assert.IsTrue(build.TryDismantle(a,out _));Assert.Greater(build.Battlefield.Grid.Revision,revision);Assert.AreEqual(0,art.Mask);Assert.AreEqual(1,build.Battlefield.Grid.MovementMultiplierAt(a.transform.position));var placement=Object.FindFirstObjectByType<PlacementController>();Assert.IsTrue(placement.SelectDismantle());placement.HoverCell(b.Anchor);Assert.AreEqual(wire.Cost/2,placement.ExpectedRefund);Assert.IsTrue(placement.PreviewVisible);Assert.IsTrue(placement.TryDismantleCurrent());Assert.IsTrue(placement.IsDismantling);placement.Select(wire);Assert.IsFalse(placement.IsDismantling);placement.Cancel();Assert.IsFalse(placement.IsInteracting);Assert.NotNull(Object.FindFirstObjectByType<BuildHud>().GetComponent<UIDocument>().rootVisualElement.Q<Button>("dismantle"));yield return null;}
  [UnityTest]public IEnumerator InvalidConsumedAndGameOverTargetsCannotRefund(){var mine=Object.FindFirstObjectByType<BuildHud>().Defenses.First(d=>d.Id=="land-mine");build.TryPlaceDefense(mine,new Vector2Int(18,8),out var defense);Assert.IsFalse(build.TryDismantle(null,out _));Assert.IsTrue(spawn.TrySpawnAt(spawn.DefaultPrefab,defense.transform.position,out _));defense.GetComponent<LandMine>().Tick(1);Assert.IsFalse(build.TryDismantle(defense,out _));yield return null;build.TryPlaceDefense(mine,new Vector2Int(19,8),out defense);build.Game.EndRun();Assert.IsFalse(build.TryDismantle(defense,out _));}
  [UnityTest]public IEnumerator OverlappingBoatsRespectCapAndWaitForCargo(){var boat=Object.FindFirstObjectByType<BoatLandingSystem>();Assert.AreEqual(5,boat.MoveSpeed);Assert.AreEqual(7,boat.Capacity);Assert.IsTrue(waves.TryStartWave());waves.Tick(.26f);Assert.AreEqual(1,boat.ActiveBoats);Assert.AreEqual(9,boat.MoveSpeed);Assert.AreEqual(12,boat.Capacity);waves.Tick(.2f);Assert.GreaterOrEqual(boat.ActiveBoats,2);Assert.AreEqual(waves.CurrentWave.ScheduledCount,waves.PendingCount+waves.AliveCount);for(int i=0;i<180 && waves.State!=WaveState.WaveComplete;i++){waves.Tick(.25f);foreach(var e in registry.Active.ToArray()){e.Movement.Tick(.25f);e.Health.TakeDefenseDamage(int.MaxValue);}yield return null;}Assert.AreEqual(WaveState.WaveComplete,waves.State);Assert.AreEqual(0,waves.PendingCount);}
  [UnityTest]public IEnumerator BossKillArmorHudRewardAndBreachResolveOnce(){var encounters=Object.FindFirstObjectByType<BossEncounterManager>();var boat=Object.FindFirstObjectByType<BoatLandingSystem>();foreach(var prefab in waves.EndlessSettings.bossEncounters.bosses){int money=build.Economy.Money;Assert.IsTrue(boat.TryDispatch(prefab,1));for(int i=0;i<40 && registry.Count==0;i++){boat.Tick(.25f);yield return null;}var boss=registry.Active.Single();Assert.AreEqual(boss,encounters.ActiveBoss);Assert.AreEqual(prefab.Definition.MaxHealth,boss.Health.MaxHealth);int hp=boss.Health.CurrentHealth;boss.Health.TakeDefenseDamage(100);Assert.AreEqual(Mathf.CeilToInt(100*(1-prefab.Definition.Armor)),hp-boss.Health.CurrentHealth);Assert.IsTrue(Object.FindFirstObjectByType<BossHUDController>().GetComponent<UIDocument>().rootVisualElement.Q("boss-panel").style.display==DisplayStyle.Flex);boss.Health.TakeDefenseDamage(int.MaxValue);boss.Health.TakeDefenseDamage(int.MaxValue);Assert.AreEqual(money+prefab.Definition.KillReward,build.Economy.Money);Assert.IsNull(encounters.ActiveBoss);boat.Cancel();yield return null;Assert.IsTrue(spawn.TrySpawnAt(prefab,spawn.Battlefield.Grid.CellToWorld(new Vector2Int(27,4)),out boss));money=build.Economy.Money;boss.Tick(100);Assert.IsFalse(border.TryBreach(boss));Assert.AreEqual(money,build.Economy.Money);yield return null;}Assert.AreEqual(2,stats.BossesKilled);Assert.AreEqual(2,stats.BossesBreached);Assert.AreEqual(1900,stats.Homicides);}
 }
}
